window.T22_DASHBOARD_UNITS = [{"unit":1,"theme":"bitter – define","cards":[{"w":"bitter","p":"adj.","d":"having a sharp, pungent taste; resentful; extremely cold","c":"苦的；嚴寒的；怨恨的","s":"The black coffee was far too bitter for the child, so he added a spoonful of sugar.","t":"這杯黑咖啡對孩子來說太苦了，所以他加了一匙糖。"},{"w":"charm","p":"n./v.","d":"the power of attracting or pleasing others; to delight greatly","c":"魅力；符咒；吸引","s":"The small mountain cottage had a rustic charm that immediately attracted many tourists.","t":"這座小山屋有一種鄉村魅力，立刻吸引了許多遊客。"},{"w":"charming","p":"adj.","d":"pleasant, delightful, and attractive","c":"迷人的；有魅力的","s":"The village is famous for its charming cobblestone streets and friendly local residents.","t":"這個村莊以其迷人的鵝卵石街道和友善的當地居民而聞名。"},{"w":"cheerful","p":"adj.","d":"noticeably happy and optimistic; causing good feelings","c":"開朗的；令人愉快的","s":"Despite facing severe financial difficulties, she always maintains a cheerful attitude toward life.","t":"儘管面臨嚴重的經濟困難，她對生活始終保持著開朗的態度。"},{"w":"crane","p":"n./v.","d":"a large long-legged bird; a lifting machine; to stretch out one's neck","c":"鶴；起重機；伸長(脖子)","s":"A pair of white cranes gracefully landed near the tranquil surface of the mountain lake.","t":"一對白鶴優雅地降落在平靜的山林湖面上。"},{"w":"cricket","p":"n.","d":"a jumping insect that makes chirping sounds; a popular bat-and-ball sport","c":"蟋蟀；板球","s":"On warm summer evenings, the constant chirping of crickets filled the peaceful garden air.","t":"在溫暖的夏日傍晚，蟋蟀持續的鳴叫聲充滿了寧靜的花園空氣。"},{"w":"criminal","p":"n./adj.","d":"a person who has committed a crime; relating to illegal acts","c":"罪犯；犯罪的","s":"Selling pirated movies and illegal counterfeit goods is considered a serious criminal act under federal law.","t":"販賣盜版電影與非法仿冒品在聯邦法律下被視為嚴重的犯罪行為。"},{"w":"darling","p":"n./adj.","d":"a dearly loved person; beloved, charming, or endearing","c":"親愛的；心愛的人","s":"She tucked her darling daughter into bed and read her a sweet bedtime story.","t":"她為自己心愛的女兒蓋好被子，並為她讀了一個甜蜜的睡前故事。"},{"w":"definition","p":"n.","d":"a statement of the exact meaning of a word; clarity or sharpness","c":"定義；清晰度","s":"When reading complex legal documents, you must look up the exact definition of technical terms.","t":"閱讀複雜的法律文件時，你必須查閱專業術語的精確定義。"},{"w":"define","p":"v.","d":"to state or describe exactly the nature, scope, or meaning of","c":"定義；明確界定","s":"The committee needs to define the scope of the new project before allocating financial resources.","t":"委員會在分配財務資源之前，需要明確界定新專案的範疇。"}]},{"unit":2,"theme":"destroy – moral","cards":[{"w":"destroy","p":"v.","d":"to damage something so severely that it no longer exists or functions","c":"破壞；摧毀；毀滅","s":"The historic city center was completely destroyed by the sudden outbreak of a devastating fire.","t":"這座歷史悠久的市中心被突如其來的毀滅性大火徹底摧毀了。"},{"w":"destruction","p":"n.","d":"the action or process of causing so much damage that something is ruined","c":"破壞；毀滅","s":"The violent Category 5 hurricane left a trail of widespread destruction along the coastal towns.","t":"這場五級強烈颶風在沿海城鎮留下了一連串大規模破壞的痕跡。"},{"w":"destructive","p":"adj.","d":"causing great and irreparable harm or damage","c":"破壞性的；毀滅性的","s":"Engaging in prolonged negative self-talk is one of the most destructive habits for mental health.","t":"長期進行負面的自我對話是對心理健康最具破壞性的習慣之一。"},{"w":"forever","p":"adv./n.","d":"for all future time; eternally; continually","c":"永遠；長久地","s":"The three university roommates made a solemn promise to remain best friends forever.","t":"這三位大學室友許下了莊嚴的承諾，要永遠當好朋友。"},{"w":"hasty","p":"adj.","d":"done with excessive speed or urgency; hurried","c":"倉促的；草率的","s":"You should carefully evaluate all potential investment risks before making a hasty decision.","t":"在做出草率的決定之前，你應該仔細評估所有潛在的投資風險。"},{"w":"haste","p":"n.","d":"excessive speed or urgency of movement or action; hurry","c":"急忙；倉促","s":"My grandfather always reminded me that haste makes waste whenever I rushed through my homework.","t":"每當我匆忙趕做功課時，祖父總是提醒我欲速則不達。"},{"w":"hatch","p":"v./n.","d":"to emerge from an egg; to devise a secret plan; an opening or door","c":"孵化；策劃(陰謀)；艙口","s":"The excited children watched the baby chicks hatch from their fragile shells in the incubator.","t":"興奮的孩子們看著小雞在孵化器中從脆弱的蛋殼中孵化出來。"},{"w":"hateful","p":"adj.","d":"arousing, deserving of, or filled with hatred","c":"可恨的；充滿仇恨的","s":"The moderator promptly removed the hateful comments posted under the candidate's campaign video.","t":"管理員迅速刪除了候選人競選影片下方張貼的仇恨言論。"},{"w":"hay","p":"n.","d":"grass that has been mown and dried for use as animal fodder","c":"乾草","s":"After working twelve grueling hours in the fields, the tired farmer was ready to hit the hay.","t":"在田裡辛勞工作了十二個小時後，疲憊的農民準備好要上床睡覺了。"},{"w":"magical","p":"adj.","d":"relating to or resembling magic; enchanting and wonderful","c":"神奇的；迷人的；魔幻的","s":"Watching the northern lights dance across the Arctic night sky was an unforgettable and magical experience.","t":"看著北極光在北極夜空中舞動，是一次難忘且奇妙的體驗。"},{"w":"moral","p":"adj./n.","d":"concerned with right and wrong conduct; a practical lesson taught by a story","c":"道德的；寓意；道德規範","s":"The whistle-blower faced a severe moral dilemma between staying loyal to his boss and telling the truth.","t":"揭弊者面臨著在忠於老闆與講出真相之間的嚴峻道德兩難困境。"}]},{"unit":3,"theme":"mostly – request","cards":[{"w":"mostly","p":"adv.","d":"as regards the greater part or for the most part; mainly","c":"主要地；大部分","s":"The weather forecast for tomorrow indicates that it will be mostly sunny with occasional light showers.","t":"明天的天氣預報顯示將會是大致晴朗且偶有陣雨的天氣。"},{"w":"outline","p":"n./v.","d":"a general sketch or summary; to give a summary of","c":"大綱；輪廓；概述","s":"Before you begin drafting your final term paper, you should write a detailed outline of your main points.","t":"在開始撰寫期末論文初稿之前，你應該先撰寫一份主要論點的詳細大綱。"},{"w":"permission","p":"n.","d":"consent or authorization given by someone in authority","c":"許可；允許","s":"Students must ask for written permission from their homeroom teacher before leaving the school campus early.","t":"學生在提早離開校園前，必須先向導師請求書面許可。"},{"w":"permit","p":"v./n.","d":"to allow something to happen; an official document giving authorization","c":"准許；允許；許可證","s":"We are planning to have a barbecue in the public park this Saturday afternoon, weather permitting.","t":"如果天氣允許的話，我們計劃本週六下午在公園舉行烤肉活動。"},{"w":"purse","p":"n./v.","d":"a small bag for carrying money; to pucker or tighten one's lips","c":"女用手提包；錢包；噘起(嘴唇)","s":"She had to dig through her large leather purse to locate her ringing smartphone and car keys.","t":"她不得不在她的大皮製手提包裡翻找，以找到響個不停的智慧型手機和車鑰匙。"},{"w":"ray","p":"n.","d":"a narrow beam of light or energy; a tiny trace of something positive","c":"光線；射線；一絲(希望)","s":"After weeks of failing negotiations, the mediator's unexpected breakthrough provided a ray of hope for peace.","t":"經過數週談判失敗後，調解人意想不到的突破為和平帶來了一線希望。"},{"w":"razor","p":"n.","d":"an instrument with a sharp blade used for shaving hair from the skin","c":"刮鬍刀；剃刀","s":"My father prefers shaving with a modern electric razor because it is faster and prevents accidental cuts.","t":"我父親更喜歡用現代電動刮鬍刀刮鬍子，因為這樣更快且能防止意外割傷。"},{"w":"regret","p":"v./n.","d":"to feel sad, repentant, or disappointed over something; sorrow","c":"後悔；遺憾；抱歉","s":"We deeply regret to inform you that your job application was not successful on this occasion.","t":"我們非常遺憾地通知您，您的求職申請這次並未成功。"},{"w":"regretful","p":"adj.","d":"feeling or expressing sorrow or remorse","c":"感到後悔的；遺憾的","s":"He gave a regretful smile as he explained why he could not attend his best friend's wedding ceremony.","t":"他帶著遺憾的微笑解釋了為何無法參加好友的婚禮。"},{"w":"request","p":"n./v.","d":"an act of asking politely for something; to ask for something formally","c":"要求；請求","s":"The popular rock band performed an acoustic version of their hit ballad at the request of the fans.","t":"這支受歡迎的搖滾樂團應粉絲的要求演唱了其熱門抒情曲的木吉他版。"}]},{"unit":4,"theme":"responsibility – skinny","cards":[{"w":"responsibility","p":"n.","d":"the state of having a duty to deal with something or of having control","c":"責任；職責","s":"As a team manager, you must take full responsibility for both the successes and failures of the project.","t":"作為團隊經理，你必須對專案的成功與失敗承擔全部責任。"},{"w":"responsible","p":"adj.","d":"having an obligation to do something; accountable for something","c":"負責任的；該承擔責任的","s":"Parents are legally and morally responsible for ensuring their young children attend school regularly.","t":"父母在法律上和道德上都有責任確保年幼的孩子定期上學。"},{"w":"rumor","p":"n./v.","d":"a currently circulating story or report of uncertain or unverified truth","c":"謠言；傳聞","s":"Rumor has it that the multinational corporation is planning to acquire its major competitor next month.","t":"傳聞說這家跨國企業正計劃在下個月收購其主要競爭對手。"},{"w":"scout","p":"n./v.","d":"a person sent out to gather information; to look for talent or locations","c":"童子軍；球探；星探；偵查","s":"A veteran baseball scout attended the regional high school tournament to evaluate promising young pitchers.","t":"一位資深棒球球探參加了地區高中聯賽，以評估有前途的年輕投手。"},{"w":"scream","p":"v./n.","d":"to give a long, loud, piercing cry or sound expressing intense emotion","c":"尖叫；尖叫聲","s":"The terrified passengers began to scream their heads off when the roller coaster plunged down the steep drop.","t":"當雲霄飛車從陡峭的坡度俯衝而下時，驚恐的乘客開始聲嘶力竭地尖叫。"},{"w":"sensible","p":"adj.","d":"chosen in accordance with wisdom or good sense; practical and reasonable","c":"明智的；合情理的；實用的","s":"Investing money in secure government bonds during an economic downturn is widely considered a sensible decision.","t":"在經濟低迷時期將資金投資於安全的政府公債，被廣泛認為是一項明智的決定。"},{"w":"shampoo","p":"n./v.","d":"a liquid preparation for washing the hair; to wash with shampoo","c":"洗髮精；洗頭；清洗(地毯)","s":"The dermatologist recommended a gentle anti-dandruff shampoo to soothe her dry and itchy scalp.","t":"皮膚科醫生推薦了一款溫和的去屑洗髮精，以舒緩她乾燥發癢的頭皮。"},{"w":"sip","p":"v./n.","d":"to drink by taking small mouthfuls; a small mouthful of liquid","c":"啜飲；一小口","s":"He paused for a thoughtful moment to take a small sip of hot black tea from his ceramic cup.","t":"他若有所思地停頓了一下，從陶瓷杯中啜飲了一小口熱紅茶。"},{"w":"skinny","p":"adj.","d":"unattractively thin; tight-fitting (of clothes)","c":"極瘦的；皮包骨的；緊身的","s":"Fashion trends in the early 2000s heavily popularized wearing tight skinny jeans paired with leather boots.","t":"2000年代初期的時尚潮流極大推廣了穿著緊身窄管牛仔褲搭配皮靴的風潮。"}]},{"unit":5,"theme":"stadium – weave","cards":[{"w":"stadium","p":"n.","d":"a sports arena with tiers of seats for spectators","c":"體育場；大型競技場","s":"Over eighty thousand passionate soccer fans gathered inside the national sports stadium for the final match.","t":"超過八萬名熱情的足球迷聚集在國家體育場內觀看決賽。"},{"w":"subtract","p":"v.","d":"to take away a number or amount from another to calculate the difference","c":"減去；扣除","s":"Elementary school children learn how to add and subtract basic numbers before moving on to multiplication.","t":"小學生在學習乘法之前，會先學習如何進行基本數字的加與減。"},{"w":"subtraction","p":"n.","d":"the mathematical process of taking one number away from another","c":"減法；扣除","s":"Mastering addition and subtraction provides a foundational mathematical skillset for young elementary students.","t":"掌握加減法為年輕小學生提供了基礎的數學技能。"},{"w":"terrific","p":"adj.","d":"of great size or intensity; extremely good; wonderful","c":"極好的；絕佳的；極大的","s":"The theatrical cast put on a terrific performance that earned a five-minute standing ovation from the audience.","t":"劇團演員帶來了極佳的演出，贏得了觀眾長達五分鐘的起立鼓掌。"},{"w":"thirst","p":"n./v.","d":"a feeling of needing to drink; a strong desire for something","c":"口渴；渴望","s":"After completing the grueling twenty-mile marathon, he drank two large bottles of water to quench his thirst.","t":"在完成了艱苦的二十英里馬拉松後，他喝了兩大瓶水來解渴。"},{"w":"threat","p":"n.","d":"a statement of an intention to inflict harm; a menace or danger","c":"威脅；恐嚇；凶兆","s":"The increasing discharge of untreated industrial waste poses a severe threat to local aquatic ecosystems.","t":"未經處理的工業廢水排放量增加，對當地水生生態系統構成了嚴重威脅。"},{"w":"threaten","p":"v.","d":"to state one's intention to take hostile action; to endanger","c":"威脅；威嚇；危及","s":"The disgruntled employee threatened to reveal confidential commercial trade secrets unless he was given a promotion.","t":"這名不滿的員工威脅要透露機密的商業商業機密，除非他獲得晉升。"},{"w":"weaken","p":"v.","d":"to make or become less strong, powerful, or effective","c":"削弱；變虛弱","s":"Chronic sleep deprivation and poor nutrition will gradually weaken the human body's natural immune system.","t":"長期睡眠不足與營養不良會逐漸削弱人體自然的免疫系統。"},{"w":"weave","p":"v./n.","d":"to form fabric by interlacing threads; to twist in and out","c":"編織；編造(故事)；穿梭","s":"The indigenous artisans carefully weave traditional bamboo baskets using techniques passed down across generations.","t":"原住民工匠運用代代相傳的技藝精心編織傳統竹籃。"}]}];
